def solve(s):
    """Run‑length encode *s*.
    *s* may be any iterable of hashable elements (including a string).
    Returns a list of [element, count] for each maximal consecutive run.
    Empty input yields an empty list.
    """
    # Guard against None or non‑iterable input.
    if s is None:
        return []
    try:
        it = iter(s)
    except TypeError:
        # Not iterable – nothing to encode.
        return []
    try:
        first = next(it)
    except StopIteration:
        return []
    result = []
    current = first
    count = 1
    for ch in it:
        if ch == current:
            count += 1
        else:
            result.append([current, count])
            current = ch
            count = 1
    result.append([current, count])
    return result

