def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles empty list and any iterable of integers.
    """
    try:
        arr = list(nums)
    except TypeError:
        return 0
    if not arr:
        return 0
    import bisect
    tails = []
    for x in arr:
        # Find position to replace in tails (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

