def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles empty input and non‑list iterables gracefully. Non‑numeric elements are ignored.
    """
    # Guard against None or non‑iterable input
    if nums is None:
        return 0
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    # Convert to list for indexing if needed
    try:
        seq = list(nums)
    except Exception:
        seq = []
    if not seq:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in seq:
        # Ignore non‑numeric values to be robust against unexpected hidden inputs
        if not isinstance(x, (int, float)):
            continue
        # Find insertion point (first element >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

